-- Fresh agentserver state schema (design v0.31). All API entities keep a
-- stable text UUID generated by the service; names remain protocol lookups.

CREATE TABLE server_state (id int PRIMARY KEY CHECK (id = 1), private_key bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ca (id int PRIMARY KEY CHECK (id = 1), cert_pem bytea NOT NULL, key_pem bytea NOT NULL);
CREATE TABLE relays (
    name text PRIMARY KEY, public_key bytea NOT NULL UNIQUE, url text NOT NULL,
    transports jsonb NOT NULL DEFAULT '{}', stun text NOT NULL DEFAULT '',
    created_at timestamptz NOT NULL DEFAULT now(), last_seen timestamptz
);
CREATE TABLE relay_tokens (
    id text PRIMARY KEY, token_hash bytea NOT NULL UNIQUE, expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(), used_at timestamptz
);
CREATE TABLE workspaces (
    name text PRIMARY KEY, base_domain text NOT NULL UNIQUE, private_key bytea NOT NULL,
    public_key bytea NOT NULL UNIQUE, relay text REFERENCES relays(name),
    routes_version bigint NOT NULL DEFAULT 1, routes_default text NOT NULL DEFAULT 'direct',
    directory_version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE join_tokens (
    id text PRIMARY KEY, workspace text NOT NULL REFERENCES workspaces(name) ON DELETE CASCADE,
    token_hash bytea NOT NULL UNIQUE, name text NOT NULL DEFAULT '', roles text[] NOT NULL DEFAULT '{}',
    expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), used_at timestamptz
);
CREATE TABLE nodes (
    workspace text NOT NULL REFERENCES workspaces(name) ON DELETE CASCADE, name text NOT NULL,
    public_key bytea NOT NULL UNIQUE, role_caps text[] NOT NULL DEFAULT '{}', joined_at timestamptz NOT NULL DEFAULT now(),
    last_seen timestamptz, handshake_ts bytea, policy_sources jsonb NOT NULL DEFAULT '{}',
    advertised_policy bytea, executor bytea, p2p_enabled boolean NOT NULL DEFAULT false,
    policy_version bigint NOT NULL DEFAULT 0, policy_hash bytea, policy_applied bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (workspace, name)
);
CREATE TABLE groups (
    workspace text NOT NULL REFERENCES workspaces(name) ON DELETE CASCADE, name text NOT NULL,
    private_key bytea NOT NULL, public_key bytea NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace, name)
);
CREATE TABLE group_members (
    workspace text NOT NULL, group_name text NOT NULL, node_name text NOT NULL,
    PRIMARY KEY (workspace, group_name, node_name),
    FOREIGN KEY (workspace, group_name) REFERENCES groups(workspace, name) ON DELETE CASCADE,
    FOREIGN KEY (workspace, node_name) REFERENCES nodes(workspace, name) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE routes (
    workspace text NOT NULL REFERENCES workspaces(name) ON DELETE CASCADE, id text NOT NULL, position int NOT NULL,
    from_subject text NOT NULL, protos text[] NOT NULL DEFAULT '{}', domains jsonb NOT NULL, to_target text NOT NULL,
    PRIMARY KEY (workspace, id)
);
CREATE TABLE policies (
    workspace text NOT NULL REFERENCES workspaces(name) ON DELETE CASCADE, id text NOT NULL, position int NOT NULL,
    statement jsonb NOT NULL, PRIMARY KEY (workspace, id)
);
CREATE TABLE services (
    workspace text NOT NULL, name text NOT NULL, node_name text NOT NULL, proto text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (workspace, name),
    FOREIGN KEY (workspace, node_name) REFERENCES nodes(workspace, name) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE certs (
    workspace text PRIMARY KEY REFERENCES workspaces(name) ON DELETE CASCADE, state text NOT NULL DEFAULT 'pending',
    cert_chain_pem bytea, key_pem bytea, not_before timestamptz, not_after timestamptz,
    issuer text NOT NULL DEFAULT '', last_error text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE revocations (
    workspace text NOT NULL REFERENCES workspaces(name) ON DELETE CASCADE, member bytea NOT NULL, issuer bytea NOT NULL,
    until_at timestamptz NOT NULL, PRIMARY KEY (workspace, member, issuer)
);
CREATE TABLE acme_accounts (id text PRIMARY KEY, key_pem bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE autocert_cache (key text PRIMARY KEY, data bytea NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE instance_settings (
    id int PRIMARY KEY CHECK (id = 1), domain text NOT NULL, domains jsonb NOT NULL DEFAULT '[]',
    dns_providers jsonb NOT NULL DEFAULT '[]', certificate_issuers jsonb NOT NULL DEFAULT '[]',
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE users (
    id text NOT NULL UNIQUE, subject text PRIMARY KEY, provider text NOT NULL, display_name text NOT NULL DEFAULT '',
    email text NOT NULL DEFAULT '', name text NOT NULL DEFAULT '', picture text NOT NULL DEFAULT '',
    instance_admin boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE workspace_members (
    id text NOT NULL UNIQUE, workspace text NOT NULL REFERENCES workspaces(name) ON DELETE CASCADE,
    subject text NOT NULL, user_id text NOT NULL DEFAULT '', role text NOT NULL CHECK (role IN ('owner', 'maintainer', 'member')),
    created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace, subject)
);
CREATE TABLE user_identities (
    id text PRIMARY KEY, user_subject text NOT NULL REFERENCES users(subject) ON DELETE CASCADE,
    provider_id text NOT NULL, subject text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled', 'deleted')),
    email_verified boolean, last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (provider_id, subject)
);
CREATE TABLE audit_events (
    id text PRIMARY KEY, occurred_at timestamptz NOT NULL DEFAULT now(), actor_kind text NOT NULL, actor_id text NOT NULL,
    action text NOT NULL, resource_type text NOT NULL, resource_id text, workspace_id text, request_id text NOT NULL,
    outcome text NOT NULL CHECK (outcome IN ('success', 'failure')), error_code text NOT NULL DEFAULT '', metadata jsonb NOT NULL DEFAULT '{}'
);
CREATE INDEX audit_events_time_idx ON audit_events (occurred_at DESC, id DESC);
CREATE INDEX audit_events_resource_idx ON audit_events (resource_type, resource_id, occurred_at DESC);
CREATE INDEX audit_events_workspace_idx ON audit_events (workspace_id, occurred_at DESC);
